mapper.select:
select a.mobile_digest,
       a.api_code,
       a.local_id,
       a.id
from b_haier_colliding_data a
         left join b_haier_colliding_data_log b on a.id = b.colliding_data_id and b.send_date = #{sendDate}
where a.local_id = #{localId}
  and a.status = 1
  and b.id is null
order by a.id limit #{pageSize}
